i tuần hoặc những dịp cần sự thanh lịch và thoải mái.","metadata":{"authority":"WEBSTORE_XML","expiresAt":null,"freshForSeconds":null,"freshnessState":"FRESH","observedAt":"2026-09-28T04:31:05.725Z","sourceVersion":"catalog-v2"},"productName":"SET QUẦN SQ675","productUrl":null},"ref":"product:SQ675","subjectRef":"SQ675"},{"content":{"description":"Màu sắc Tone kem phối họa tiết thổ cẩm hồng pastel và be nhạt, mang đến tổng thể ngọt ngào, thanh lịch và nữ tính. Set được may từ vải thô đũi cao cấp với bề mặt mềm mịn, thoáng khí và thấm hút tốt, mang lại cảm giác nhẹ nhàng, dễ chịu khi mặc Set gồm á kết hợp quần short lưng chun đồng bộ, chi tiết bèo xếp tầng ở gấu áo giúp tôn vòng eo và tạo hiệu ứng mềm mại, nữ tính. Quần short form suông, chiều dài vừa vặn giúp tôn dáng và tạo sự thoải mái khi vận động.","metadata":{"authority":"WEBSTORE_XML","expiresAt":null,"freshForSeconds":null,"freshnessState":"FRESH","observedAt":"2026-09-28T04:31:05.725Z","sourceVersion":"catalog-v2"},"productName":"SET QUẦN UYỂN HOA","productUrl":null},"presentation":{"displayName":"SET QUẦN UYỂN HOA","productId":"SQ748","provenance":{"content":{"authority":"WEBSTORE_XML","expiresAt":null,"freshForSeconds":null,"freshnessState":"FRESH","observedAt":"2026-09-28T04:31:05.725Z","sourceVersion":"catalog-v2"},"contentHash":"1c6bb77c0ba18c1518f96e2ede3cfd26724f411d2d5fbd72320d5af404c3ee84","freshnessState":"FRESH","identity":{"authority":"GOOGLE_SHEETS_PRODUCT_REGISTRY","expiresAt":null,"freshForSeconds":null,"freshnessState":"FRESH","observedAt":"2026-09-28T04:31:05.725Z","sourceVersion":"catalog-v2"},"inventory":{"authority":"PANCAKE_POS","expiresAt":"2026-10-26T07:34:32.513Z","freshForSeconds":172800,"freshnessState":"FRESH","observedAt":"2026-10-24T07:34:32.513Z","sourceVersion":"p2-default"}},"schemaVersion":1,"variants":[{"color":"__NO_COLOR__","size":"S","variantId":"0ad0164e90dca7a493f931d0872c2255"},{"color":"__NO_COLOR__","size":"M","variantId":"ae88477bd0769ec0b7bc5d5506939479"},{"color":